import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"ADR-003 HCP Terraform for state","description":"","frontmatter":{},"headers":[],"relativePath":"adr/003-hcp-terraform-state.md","filePath":"adr/003-hcp-terraform-state.md","lastUpdated":1786471258000}`),a={name:`adr/003-hcp-terraform-state.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /adr/003-hcp-terraform-state.md for this page in Markdown format</div><h1 id="adr-003-hcp-terraform-for-state" tabindex="-1">ADR-003 HCP Terraform for state <a class="header-anchor" href="#adr-003-hcp-terraform-for-state" aria-label="Permalink to “ADR-003 HCP Terraform for state”">​</a></h1><p><strong>Status:</strong> Accepted</p><p><strong>Date:</strong> 2026-08-09 <strong>Tags:</strong> infrastructure, terraform, state</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to “Problem”">​</a></h2><ul><li>Terraform state for this project holds a database password: Hyperdrive stores the origin credentials as discrete fields, so they are written to state. It needs encryption at rest, locking, and a recoverable history.</li><li>Object-storage backends have a bootstrap problem – you must provision, by hand, the bucket that holds the state that provisions everything else – and the obvious choice here, R2, has no object versioning, so a corrupted state has no rollback.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ul><li>Use a <code>cloud</code> block against HCP Terraform, with the host, organization and workspace committed in each root – <code>app.terraform.io</code> plus placeholder organization and workspace names that adopters replace with their own. A fork that has not renamed them cannot initialize against its own HCP setup, so it touches nothing by accident.</li><li>Commit the coordinates rather than passing <code>TF_WORKSPACE</code>. Terraform refuses to run when <code>TF_WORKSPACE</code> disagrees with <code>workspaces.name</code>, and consults <code>TF_CLOUD_HOSTNAME</code> only when <code>hostname</code> is omitted, so ambient shell state cannot retarget a root at another environment&#39;s state or another Terraform host. That covers commands an output <code>precondition</code> never could: <code>output</code>, <code>import</code> and the <code>state</code> subcommands do not evaluate output preconditions, whatever else they read.</li><li>Use Remote execution mode, with the Cloudflare token and Terraform inputs held as workspace variables. A remote run receives <code>TF_VAR_*</code> from the caller but no other environment variables, so the provider credential can only come from the workspace; CI needs exactly one secret (<code>TF_API_TOKEN</code>). Inputs such as <code>database_url</code> are defaults a caller can still override per run.</li><li>Ship one backend, not a choice of several. At two environments and four resources, options cost more than they give.</li></ul><h2 id="alternatives-brief" tabindex="-1">Alternatives (brief) <a class="header-anchor" href="#alternatives-brief" aria-label="Permalink to “Alternatives (brief)”">​</a></h2><ul><li><strong>S3-compatible backend on Cloudflare R2</strong> – keeps everything on one vendor, and <code>use_lockfile = true</code> works because R2 supports conditional writes. Rejected for the manual bucket bootstrap, a run of <code>skip_*</code> compatibility flags per environment, and no versioning for recovery.</li><li><strong>Local state</strong> – untenable: both environments are shared, and the state carries a password.</li><li><strong>Local execution mode with HCP for state only</strong> – still supported, and documented for anyone who wants it, but it puts production credentials back on developer machines for no gain here.</li></ul><h2 id="impact" tabindex="-1">Impact <a class="header-anchor" href="#impact" aria-label="Permalink to “Impact”">​</a></h2><ul><li>Positive: no state-storage bootstrap – the workspaces are created once in the UI, but there is no chicken-and-egg bucket to provision first; state encrypted and versioned; locking built in; GitHub stores no Cloudflare or database credentials, only the HCP token.</li><li>Negative/Risks: adds a HashiCorp account to an otherwise Cloudflare-only stack, and workspace variables are configured in a web UI rather than the repository.</li><li>Remote execution isolates less than it looks. Terraform forwards local <code>TF_VAR_*</code> values as run-specific variables, and those <a href="https://developer.hashicorp.com/terraform/cloud-docs/variables/managing-variables" target="_blank" rel="noreferrer">outrank ordinary workspace variables</a>, so an exported <code>TF_VAR_project_slug</code> can propose renaming every resource. Priority variable sets would lock a value down; this starter does not use them: the CI workflow runs only committed <code>main</code> configuration and passes no <code>TF_VAR_*</code> of its own, and an interactive run shows the override in the plan before anyone confirms it.</li><li>Five workspace settings have no <code>cloud</code> block equivalent and so live outside version control: the CLI-driven workflow (a VCS-linked workspace refuses remote applies), Remote execution mode (Local mode ignores workspace variables), <strong>Terraform Working Directory</strong> set to <code>envs/&lt;env&gt;</code> (otherwise the uploaded configuration omits the shared <code>modules/</code> directory the roots reference), the <strong>Terraform Version</strong> (a new workspace pins whatever release was current when it was created, which <code>required_version</code> can only reject, not select), and the variables themselves. <code>infra/README.md</code> enumerates them.</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to “Links”">​</a></h2><ul><li>Code/Docs: <code>infra/README.md</code>, <code>infra/envs/*/main.tf</code>, <a href="/specs/infra-terraform">Infrastructure spec</a></li><li>Related ADRs: <a href="/adr/002-terraform-wrangler-boundary">ADR-002</a></li></ul>`,14)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};